 review.append({'primarySourceFrameId':r['frameId'],'sourcePNG':r['file'],'sourcePNGsha256':r['fileSha256'],'sourceCanvas':list(im.size),'sourceOriginal':r['sourceAtlas'],'poseTags':r['poseTags'],'label':label,'normalOutputCanvas':[192,192],'normalWorldCanvas':[192,192],'density':1,'bboxAlpha128':[int(xx.min()),int(yy.min()),int(xx.max()+1),int(yy.max()+1)],'lookReuseDecision':decision,'acceptedLookReuse':False})
